-- precondition-sql-check expectedResult:0  SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'iot_sys_unit') AS column_exists;
CREATE TABLE IF NOT EXISTS `iot_sys_unit` (
                                              `id` bigint(20) NOT NULL COMMENT 'id',
    `unit_code` varchar(100) DEFAULT '' COMMENT '单位code',
    `unit_name` varchar(20) DEFAULT NULL COMMENT '单位名称',
    `unit_type` varchar(20) DEFAULT NULL COMMENT '单位类型',
    `unit_status` tinyint(1) DEFAULT '0' COMMENT '状态0正常 1停用',
    `remark` varchar(500) DEFAULT NULL COMMENT '备注',
    `deleted` bigint(20) DEFAULT NULL,
    `create_by` varchar(20) DEFAULT NULL,
    `create_time` datetime DEFAULT NULL,
    `update_by` varchar(20) DEFAULT NULL,
    `update_time` datetime DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='单位表';


-- changeset xiaofeng:ddl-2
-- preconditions onFail:CONTINUE
-- precondition-sql-check expectedResult:0  SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'iot_md_product_prop' AND column_name='unit_code') AS column_exists;
ALTER TABLE `iot_md_product_prop` ADD COLUMN `unit_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '单位编码';

update iot_md_product_prop a set unit_code = (select b.item_label from iot_sys_dict_item b where b.id = a.unit_id);
update iot_md_product_prop a set unit_code = (select b.unit_code from iot_sys_unit b where b.unit_name = a.unit_code);